import {checklistFacts,factLabel} from './checklist-facts.js?v=7';
const base={stage:[['new','Mới thành lập'],['running','Đang hoạt động'],['changing','Đang thay đổi'],['paused','Tạm ngừng']],employees:[['0','Không có lao động'],['1-9','1–9 nhân viên'],['10-49','10–49 nhân viên'],['50-99','50–99 nhân viên'],['100+','Từ 100 nhân viên']],activity:[['goods','Bán hàng hóa'],['services','Dịch vụ'],['manufacturing','Sản xuất'],['digital','Hoạt động số']],channels:[['direct','Trực tiếp'],['marketplace','Sàn thương mại điện tử'],['social','Mạng xã hội'],['website','Website']],places:[['office','Văn phòng'],['store','Cửa hàng'],['warehouse','Kho'],['factory','Nhà xưởng']],signals:[['invoice','Hóa đơn'],['customerData','Dữ liệu khách hàng'],['notary','Công chứng'],['regulated','Ngành có điều kiện'],['smallEnterprise','Doanh nghiệp nhỏ'],['copyrightAssets','Tài sản bản quyền'],['digitalPublishing','Xuất bản số'],['foreign','Yếu tố nước ngoài'],['crossborder','Hoạt động xuyên biên giới'],['ads','Quảng cáo']],'site.kind':[['office','Văn phòng'],['store','Cửa hàng'],['warehouse','Kho'],['factory','Nhà xưởng']]};
export const reviewerFields=['stage','employees','employeeCount','province','activity','channels','places','signals','site.kind','site.province','event.type',...checklistFacts.map(x=>x.key)];
const options=k=>base[k]||checklistFacts.find(f=>f.key===k)?.options;
const ops={eq:'là',in:'thuộc một trong',has:'có',gt:'lớn hơn',gte:'từ mức',lt:'nhỏ hơn',lte:'không quá',exists:'đã được xác nhận'};
export function ruleText(r){if(r.all)return 'Tất cả điều kiện: '+r.all.map(ruleText).join('; ');if(r.any)return 'Ít nhất một điều kiện: '+r.any.map(ruleText).join('; ');if(r.not)return 'Không thuộc trường hợp: '+ruleText(r.not);const value=Array.isArray(r.value)?r.value.map(v=>options(r.fact)?.find(x=>x[0]===v)?.[1]??v).join(', '):options(r.fact)?.find(x=>x[0]===r.value)?.[1]??r.value;return `${factLabel(r.fact)} ${ops[r.op]||r.op}${r.op==='exists'?'':' '+(value??'chưa chọn')}`;}
export function latestVersions(rows){const map=new Map();for(const v of rows){const id=v.obligationId||v.id;if(!map.has(id)||map.get(id).version<v.version)map.set(id,v);}return [...map.values()];}
export function reviewGroups(rows,groups){const latest=latestVersions(rows);return Object.entries(groups).map(([key,label])=>{const items=latest.filter(v=>v.contentJson.group===key);return {key,label,items,pending:items.filter(v=>['DRAFT','IN_REVIEW'].includes(v.status)).length,published:items.filter(v=>v.status==='PUBLISHED').length};});}
const operators=k=>k==='employeeCount'?['eq','in','gt','gte','lt','lte','exists']:['activity','channels','places','signals'].includes(k)?['has','exists']:['eq','in','exists'];
export function renderRuleBuilder(rule,esc,path='root'){
 if(rule.all||rule.any){const kind=rule.all?'all':'any',children=rule[kind];return `<div class="rule-builder-group"><label>Kết hợp điều kiện<select name="rule-kind-${path}" data-rule-change><option value="all" ${kind==='all'?'selected':''}>Tất cả điều kiện phải đúng</option><option value="any" ${kind==='any'?'selected':''}>Chỉ cần một điều kiện đúng</option></select></label>${children.map((r,i)=>`<div class="rule-builder-child">${renderRuleBuilder(r,esc,path+'.'+i)}<button type="button" class="text-action" data-rule-remove="${path}.${i}" ${children.length===1?'disabled':''}>Bỏ điều kiện</button></div>`).join('')}<button type="button" class="secondary-button" data-rule-add="${path}">Thêm điều kiện</button></div>`;}
 if(rule.not)return `<div class="rule-builder-group"><strong>Không thuộc trường hợp dưới đây</strong>${renderRuleBuilder(rule.not,esc,path+'.not')}</div>`;
 const opts=options(rule.fact),type=rule.fact==='employeeCount'?'number':checklistFacts.find(f=>f.key===rule.fact)?.kind==='date'?'date':'text';
 const value=rule.op==='exists'?'':rule.op==='in'&&opts?`<select name="rule-value-${path}" multiple required>${opts.map(([k,t])=>`<option value="${esc(k)}" ${(rule.value||[]).includes(k)?'selected':''}>${esc(t)}</option>`).join('')}</select>`:rule.op==='in'?`<input name="rule-value-${path}" value="${esc((rule.value||[]).join(', '))}" placeholder="Các giá trị, cách nhau bằng dấu phẩy" required>`:opts?`<select name="rule-value-${path}" required><option value="">Chọn giá trị</option>${opts.map(([k,t])=>`<option value="${esc(k)}" ${rule.value===k?'selected':''}>${esc(t)}</option>`).join('')}</select>`:`<input name="rule-value-${path}" type="${type}" value="${esc(rule.value??'')}" required>`;
 return `<div class="rule-builder-row"><label>Thông tin doanh nghiệp<select name="rule-fact-${path}" data-rule-change required><option value="">Chọn thông tin</option>${reviewerFields.map(k=>`<option value="${esc(k)}" ${rule.fact===k?'selected':''}>${esc(factLabel(k))}</option>`).join('')}</select></label><label>Điều kiện<select name="rule-op-${path}" data-rule-change>${operators(rule.fact).map(k=>`<option value="${k}" ${rule.op===k?'selected':''}>${ops[k]}</option>`).join('')}</select></label>${value?`<label>Giá trị${value}</label>`:''}</div>`;
}
export function readRule(model,form,path='root'){
 if(model.all||model.any){const children=model.all||model.any,kind=form.get('rule-kind-'+path)|| (model.all?'all':'any');return {[kind]:children.map((r,i)=>readRule(r,form,path+'.'+i))};}
 if(model.not)return {not:readRule(model.not,form,path+'.not')};
 const fact=String(form.get('rule-fact-'+path)||''),chosen=String(form.get('rule-op-'+path)||'eq'),op=operators(fact).includes(chosen)?chosen:operators(fact)[0],raw=String(form.get('rule-value-'+path)??'').trim(),convert=x=>fact==='employeeCount'&&x!==''?Number(x):x;
 return {fact,op,...(op==='exists'?{}:{value:fact!==model.fact?'':op==='in'?(options(fact)?form.getAll('rule-value-'+path):raw.split(',')).map(x=>convert(String(x).trim())).filter(x=>x!==''):convert(raw)})};
}
export function alterRule(model,path,operation){const tokens=path.split('.').slice(1);let parent=model;for(const token of tokens.slice(0,-1))parent=token==='not'?parent.not:(parent.all||parent.any)[Number(token)];if(operation==='remove'){const list=parent.all||parent.any;if(list.length>1)list.splice(Number(tokens.at(-1)),1);return model;}let node=model;for(const token of tokens)node=token==='not'?node.not:(node.all||node.any)[Number(token)];const leaf={fact:'',op:'eq',value:''};if(node.all||node.any)(node.all||node.any).push(leaf);else if(!tokens.length)return {all:[model,leaf]};return model;}
const shiftText=d=>d.shift==='NEXT_WORKING_DAY'?' · lùi sang ngày làm việc kế tiếp nếu trùng ngày nghỉ':'';
export function deadlineText(d){return deadlineBase(d)+shiftText(d);}
function deadlineBase(d){const day=d.day==='LAST'?'ngày cuối tháng':'ngày '+d.day;switch(d.kind){case 'NONE':return 'Không có ngày hạn cụ thể';case 'FIXED':return 'Hạn cố định: '+d.date;case 'OFFSET':return `${d.days} ngày từ ${d.trigger==='FOUNDED'?'ngày thành lập':'ngày phát sinh sự kiện'}`;case 'ANNUAL':return `Hằng năm: ${day}, tháng ${d.month}`;case 'QUARTERLY':return `Theo quý: ${day}, sau cuối quý ${d.monthsAfterEnd} tháng (hệ thống tự tạo việc cho từng quý)`;case 'MONTHLY':return `Theo tháng: ${day}, sau cuối tháng ${d.monthsAfterEnd} tháng (hệ thống tự tạo việc cho từng tháng)`;case 'FISCAL_YEAR_END_OFFSET':return `${d.months||0} tháng và ${d.days||0} ngày sau ngày kết thúc kỳ kế toán năm (tự tính từng năm)`;case 'DATE_OFFSET':return `${d.months||0} tháng và ${d.days||0} ngày từ ${factLabel(d.triggerFact)}`;case 'PERIOD_END':return `${day}, sau ${factLabel(d.periodEndFact)} ${d.monthsAfterEnd} tháng (cách cũ: DN phải tự nhập kỳ; nên đổi sang Theo tháng/Theo quý)`;case 'REVIEW_PERIOD':return 'Rà soát theo năm; không tự đặt ngày đến hạn';default:return 'Cần đối chiếu cách tính hạn';}}
export const deadlineKinds={NONE:'Không có ngày hạn cụ thể',FIXED:'Một ngày cố định',OFFSET:'Sau ngày thành lập / sự kiện',MONTHLY:'Theo tháng',QUARTERLY:'Theo quý',ANNUAL:'Hằng năm',FISCAL_YEAR_END_OFFSET:'Sau cuối kỳ kế toán năm',DATE_OFFSET:'Sau một mốc trong hồ sơ',PERIOD_END:'Sau cuối kỳ do DN nhập (cách cũ)',REVIEW_PERIOD:'Rà soát theo năm'};
const SHIFTABLE=['FIXED','OFFSET','MONTHLY','QUARTERLY','ANNUAL','FISCAL_YEAR_END_OFFSET','DATE_OFFSET','PERIOD_END'];
export function renderDeadlineBuilder(d,esc){const input=(k,label,type='number',value=d[k]??'')=>`<label>${label}<input name="deadline-${k}" type="${type}" value="${esc(value)}" ${type==='number'?'min="0"':''} required></label>`,select=(k,label,opts)=>`<label>${label}<select name="deadline-${k}">${opts.map(([v,t])=>`<option value="${esc(v)}" ${String(d[k])===String(v)?'selected':''}>${esc(t)}</option>`).join('')}</select></label>`,days=[...Array.from({length:28},(_,i)=>[i+1,'Ngày '+(i+1)]),['LAST','Ngày cuối tháng']],dates=checklistFacts.filter(f=>f.kind==='date'&&(!f.deprecated||f.key===d.triggerFact||f.key===d.periodEndFact)).map(f=>[f.key,f.label]);let fields='';
 if(d.kind==='FIXED')fields=input('date','Ngày đến hạn','date');
 if(d.kind==='OFFSET')fields=select('trigger','Tính từ',[['FOUNDED','Ngày thành lập'],['EVENT','Ngày phát sinh sự kiện']])+input('days','Số ngày sau mốc');
 if(d.kind==='ANNUAL')fields=select('month','Tháng',Array.from({length:12},(_,i)=>[i+1,'Tháng '+(i+1)]))+select('day','Ngày',days);
 if(d.kind==='QUARTERLY')fields=select('monthsAfterEnd','Sau cuối quý',[[1,'1 tháng'],[2,'2 tháng'],[3,'3 tháng']])+select('day','Ngày',days);
 if(d.kind==='MONTHLY')fields=select('monthsAfterEnd','Sau cuối tháng',[[1,'1 tháng'],[2,'2 tháng'],[3,'3 tháng']])+select('day','Ngày',days);
 if(d.kind==='FISCAL_YEAR_END_OFFSET')fields=input('months','Số tháng sau cuối kỳ kế toán năm')+input('days','Số ngày thêm');
 if(d.kind==='DATE_OFFSET')fields=select('triggerFact','Mốc trong hồ sơ',dates)+input('months','Số tháng sau mốc')+input('days','Số ngày thêm');
 if(d.kind==='PERIOD_END')fields=select('periodEndFact','Kỳ kê khai',dates.filter(([k])=>['socialInsuranceContributionPeriodEndDate','vatMonthlyPeriodEndDate','vatQuarterPeriodEndDate'].includes(k)))+select('monthsAfterEnd','Sau cuối kỳ',[[1,'1 tháng'],[2,'2 tháng'],[3,'3 tháng']])+select('day','Ngày',days);
 // Only legal text decides whether a deadline falling on a day off moves; days are moved only for calendar years approved in working-calendar.ts.
 if(SHIFTABLE.includes(d.kind))fields+=select('shift','Nếu ngày cuối cùng trùng ngày nghỉ',[['NONE','Giữ nguyên ngày'],['NEXT_WORKING_DAY','Lùi sang ngày làm việc kế tiếp (cần căn cứ)']]);
 return `<div class="deadline-builder"><label>Cách xác định thời hạn<select name="deadline-kind" data-deadline-change>${Object.entries(deadlineKinds).map(([k,t])=>`<option value="${k}" ${d.kind===k?'selected':''}>${t}</option>`).join('')}</select></label>${fields}</div>`;
}
export function readDeadline(form){const d=readDeadlineBase(form);return SHIFTABLE.includes(d.kind)&&form.get('deadline-shift')==='NEXT_WORKING_DAY'?{...d,shift:'NEXT_WORKING_DAY'}:d;}
function readDeadlineBase(form){const kind=String(form.get('deadline-kind')),value=k=>String(form.get('deadline-'+k)),number=k=>Number(value(k)),day=()=>value('day')==='LAST'?'LAST':number('day');switch(kind){case 'NONE':return {kind};case 'FIXED':return {kind,date:value('date')};case 'OFFSET':return {kind,trigger:value('trigger'),days:number('days')};case 'ANNUAL':return {kind,month:number('month'),day:day()};case 'QUARTERLY':case 'MONTHLY':return {kind,monthsAfterEnd:number('monthsAfterEnd'),day:day()};case 'FISCAL_YEAR_END_OFFSET':return {kind,months:number('months'),days:number('days')};case 'DATE_OFFSET':return {kind,triggerFact:value('triggerFact'),months:number('months'),days:number('days')};case 'PERIOD_END':return {kind,periodEndFact:value('periodEndFact'),monthsAfterEnd:number('monthsAfterEnd'),day:day()};case 'REVIEW_PERIOD':return {kind,period:'YEAR'};default:throw Error('Chọn cách xác định thời hạn.');}}
// Editorial triage only (not a legal judgement): which drafts unblock the most companies once approved.
const CORE_GROUPS=['tax','insurance','labor','accounting','company'],SECTOR_GROUPS=['food','environment','fire','hungyen'];
const ruleFacts=r=>r?.all||r?.any?(r.all||r.any).flatMap(ruleFacts):r?.not?ruleFacts(r.not):r?.fact?[r.fact]:[];
export function draftPriority(c){
 const facts=[...new Set(ruleFacts(c.rule))],tier=f=>checklistFacts.find(x=>x.key===f)?.tier||'OBSERVABLE',trigger=c.deadline?.triggerFact||c.deadline?.periodEndFact;
 const conclusions=facts.filter(f=>tier(f)==='LEGAL_CONCLUSION').length,periods=[...new Set([...facts,...(trigger?[trigger]:[])])].filter(f=>tier(f)==='PERIOD').length,reasons=[];let score=0;
 if(CORE_GROUPS.includes(c.group)){score+=30;reasons.push('nhóm nghĩa vụ phổ biến');}else if(SECTOR_GROUPS.includes(c.group)){score-=10;reasons.push('chỉ cho ngành/địa phương cụ thể');}
 if(!conclusions&&!periods&&facts.length<=2){score+=30;reasons.push('xác định được từ vài câu hỏi cơ bản');}
 if(conclusions){score-=15*conclusions;reasons.push(`cần ${conclusions} kết luận pháp lý (nên duyệt quy tắc dẫn xuất cùng lúc)`);}
 if(periods){score-=10*periods;reasons.push('phụ thuộc ngày của từng kỳ do DN nhập');}
 const kind=c.deadline?.kind;if(kind&&!['NONE','REVIEW_PERIOD'].includes(kind)){score+=25;reasons.push('có hạn cụ thể để nhắc');}else if(kind==='REVIEW_PERIOD'){score+=10;reasons.push('rà soát hằng năm');}
 return {score,reasons,facts};
}
